   Number("重要消息（秒）",Current.ImportantSeconds,1,120,v=>Save(s=>s with{ImportantSeconds=(int)v}));
   Number("呼叫提醒（秒）",Current.CallingSeconds,1,3600,v=>Save(s=>s with{CallingSeconds=(int)v}));
